import{_ as r,C as n,c as s,o as i,a3 as e,G as a}from"./chunks/framework.Dokpd4od.js";const y=JSON.parse('{"title":"Stock report","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/reporting/stock-report.md","filePath":"master/supply-chain/inventories/reporting/stock-report.md","lastUpdated":1792041590000}'),l={name:"master/supply-chain/inventories/reporting/stock-report.md"};function d(c,t,p,u,h,g){const o=n("ImagePopup");return i(),s("div",null,[t[0]||(t[0]=e('<h1 id="stock-report" tabindex="-1">Stock report <a class="header-anchor" href="#stock-report" aria-label="Permalink to &quot;Stock report&quot;">​</a></h1><p>The stock report shows how much of each product you hold in each location. It also shows how much is reserved for orders. Use it to answer &quot;do we have it, and where?&quot; in seconds.</p><blockquote><p><strong>In simple words:</strong> A live list of stock by product and place.</p></blockquote><p>Open it from <code>Inventory → Reporting → Locations</code>. The page title is <strong>Product Quantities</strong>.</p><div class="warning custom-block"><p class="custom-block-title">Gate</p><p><strong>Location</strong>, <strong>Lot / Serial Numbers</strong> and <strong>Package</strong> columns show only when <code>Locations</code>, <code>Lots &amp; Serial Numbers</code> and <code>Packages</code> are on in <code>Inventory → Settings</code>.</p></div><h2 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h2><ul><li><strong>Default:</strong> all rows. The page opens on <strong>Internal Locations</strong>.</li><li><strong>Internal Locations:</strong> stock in your warehouse.</li><li><strong>Transit Locations:</strong> stock on the way.</li><li><strong>On Hand:</strong> rows with a quantity above zero.</li><li><strong>To Count:</strong> rows due for a count.</li><li><strong>To Apply:</strong> rows with a count waiting to be applied.</li></ul>',7)),a(o,{src:"/images1/inventory/rep_stock_report.png",alt:"Product Quantities list with tabs and the columns On Hand Quantity and Reserved Quantity"}),t[1]||(t[1]=e('<h2 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h2><ul><li><strong>Product, Location, Storage Category, Package, Lot / Serial Numbers</strong>.</li><li><strong>On Hand Quantity:</strong> physically in the location. You can type a new value in the cell.</li><li><strong>Delete:</strong> a red button at the end of each row.</li><li><strong>Reserved Quantity:</strong> held for orders that are not yet shipped.</li><li><strong>Unit:</strong> the unit of measure.</li></ul><p>A <strong>Summary</strong> block below the table totals the rows on this page and all rows. Available stock is on hand minus reserved. Example: 106 Camping Hammocks on hand and 20 reserved leaves 86 free.</p><h2 id="group-by-and-filters" tabindex="-1">Group by and filters <a class="header-anchor" href="#group-by-and-filters" aria-label="Permalink to &quot;Group by and filters&quot;">​</a></h2><p>Group by Product, Product Category, Location, Storage Category, Lot / Serial Number, Package or Company. After you pick a group, an <strong>Ascending</strong> or <strong>Descending</strong> choice appears. Filters cover Warehouse, Location, Product Category, Storage Category, Package, Package Type and Lot/Serial Number.</p>',5)),a(o,{src:"/images1/inventory/rep_stock_group_by.png",alt:"Product Quantities grouped by Location with filters open"}),t[2]||(t[2]=e('<h2 id="edit-in-place-or-adjust" tabindex="-1">Edit in place or adjust <a class="header-anchor" href="#edit-in-place-or-adjust" aria-label="Permalink to &quot;Edit in place or adjust&quot;">​</a></h2><p>The page has an <strong>Add Quantity</strong> button, like the Quantities page. Both change the same stock.</p><table tabindex="0"><thead><tr><th>Approach</th><th>Best for</th></tr></thead><tbody><tr><td>Edit in the report</td><td>Quick fix of one row</td></tr><tr><td><a href="./../adjustments/inventory-adjustments.html">Inventory adjustments</a></td><td>Counted quantity, difference, then Apply</td></tr><tr><td><a href="./../adjustments/scrap.html">Scrap</a></td><td>Destroyed goods</td></tr></tbody></table><p>Prefer adjustments for real counts. They record a clear difference and a stock move.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Reporting overview</a></li><li><a href="./moves-history.html">Moves history</a></li><li><a href="./../adjustments/inventory-adjustments.html">Inventory adjustments</a></li><li><a href="./../warehouses/locations.html">Locations</a></li></ul>',6))])}const _=r(l,[["render",d]]);export{y as __pageData,_ as default};
